package com.bank.net;

import java.util.*;
import java.util.logging.Logger;

// Models CoreDNS (name -> ClusterIP) plus the EndpointSlice (ClusterIP -> ready Pod IPs).
public class ServiceRegistry {
    private static final Logger log = Logger.getLogger(ServiceRegistry.class.getName());

    private final Map<String, String> dns = new HashMap<>();            // service name -> ClusterIP
    private final Map<String, List<String>> endpoints = new HashMap<>(); // ClusterIP -> Pod IPs
    private boolean dnsEgressBlocked = false;                           // NetworkPolicy blocks port 53
    private int rr = 0;

    public void registerService(String name, String clusterIp, List<String> podIps) {
        dns.put(name, clusterIp);
        endpoints.put(clusterIp, new ArrayList<>(podIps));
        log.info(() -> "registered " + name + " -> " + clusterIp + " endpoints=" + podIps);
    }

    // CoreDNS lookup. Throws if egress to DNS is blocked (the real bug we hit).
    public String resolve(String serviceName) {
        if (dnsEgressBlocked) {
            throw new IllegalStateException("UnknownHostException: " + serviceName
                    + " (egress to CoreDNS:53 blocked by NetworkPolicy)");
        }
        String ip = dns.get(serviceName);
        if (ip == null) throw new IllegalStateException("NXDOMAIN: " + serviceName);
        return ip;
    }

    // kube-proxy picks one ready Pod IP behind the ClusterIP (round-robin).
    public String pickEndpoint(String clusterIp) {
        List<String> eps = endpoints.getOrDefault(clusterIp, List.of());
        if (eps.isEmpty()) throw new IllegalStateException("Service has ZERO endpoints (selector/readiness?)");
        return eps.get((rr++) % eps.size());
    }

    public void blockDnsEgress() { dnsEgressBlocked = true; }
    public void allowDnsEgress() { dnsEgressBlocked = false; }
    public boolean isDnsBlocked() { return dnsEgressBlocked; }
    public List<String> endpointsOf(String clusterIp) { return endpoints.getOrDefault(clusterIp, List.of()); }
}
