package com.bank.net;

import java.math.BigDecimal;
import java.util.logging.Logger;

public class PaymentClient {
    private static final Logger log = Logger.getLogger(PaymentClient.class.getName());
    private final ServiceRegistry registry;

    public PaymentClient(ServiceRegistry registry) { this.registry = registry; }

    public void transfer(String serviceName, Account from, Account to, BigDecimal amount) {
        String clusterIp = registry.resolve(serviceName);             // CoreDNS
        String podIp = registry.pickEndpoint(clusterIp);              // kube-proxy
        log.info(() -> "resolved " + serviceName + " -> " + clusterIp + " -> pod " + podIp);
        from.debit(amount); to.credit(amount);
        log.info(() -> "transfer " + from.getAccountId() + "->" + to.getAccountId()
                + " Rs." + amount + " via " + podIp + " SUCCESS");
    }
}
