package com.bank.net;

import java.util.logging.Logger;

// Walks the DNS debugging layers in order, like a real on-call runbook.
public class DnsDebugger {
    private static final Logger log = Logger.getLogger(DnsDebugger.class.getName());
    private final ServiceRegistry registry;

    public DnsDebugger(ServiceRegistry registry) { this.registry = registry; }

    public void diagnose(String serviceName, String clusterIp) {
        log.info("1. check name/namespace FQDN: " + serviceName + ".prod.svc.cluster.local");
        log.info("2. check /etc/resolv.conf: nameserver = CoreDNS ClusterIP, search=prod.svc.cluster.local");
        try {
            registry.resolve(serviceName);
            log.info("3. nslookup " + serviceName + " OK");
        } catch (RuntimeException e) {
            log.severe("3. nslookup FAILED: " + e.getMessage());
        }
        boolean hasEndpoints = !registry.endpointsOf(clusterIp).isEmpty();
        log.info("4. kubectl get endpointslices: " + (hasEndpoints ? "has endpoints" : "ZERO endpoints"));
        log.info("5. check CoreDNS pods + logs (kube-system)");
        if (registry.isDnsBlocked()) {
            log.severe("6. ROOT CAUSE: NetworkPolicy blocks egress to CoreDNS:53 -> allow UDP/TCP 53");
        } else {
            log.info("6. NetworkPolicy allows egress to DNS");
        }
    }
}
