package com.bank.net;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class ServiceDiscoveryDemo {
    private static final Logger log = Logger.getLogger(ServiceDiscoveryDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        ServiceRegistry registry = new ServiceRegistry();
        registry.registerService("transfer-service", "10.96.0.42",
                List.of("10.244.1.5", "10.244.2.8", "10.244.3.3"));

        PaymentClient client = new PaymentClient(registry);

        // Happy path: resolve name, load-balance to a Pod, do the transfer
        client.transfer("transfer-service", rajesh, priya, new BigDecimal("50000"));

        // Failure injected: a NetworkPolicy blocks egress to CoreDNS:53
        registry.blockDnsEgress();
        try {
            client.transfer("transfer-service", rajesh, priya, new BigDecimal("10000"));
        } catch (RuntimeException e) {
            log.severe("transfer failed: " + e.getMessage());
            new DnsDebugger(registry).diagnose("transfer-service", "10.96.0.42");
        }
    }
}
