apiVersion: v1
kind: Service
metadata:
  name: transfer-service
  namespace: prod
spec:
  type: ClusterIP
  selector:
    app: transfer          # must match Pod labels or endpoints will be EMPTY
  ports:
    - port: 8080
      targetPort: 8080
---
# k8s/ingress.yaml — external HTTP routing: host/path -> Service
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata:
  name: nbi-ingress
  namespace: prod
spec:
  rules:
    - host: api.nbi.com
      http:
        paths:
          - path: /transfers
            pathType: Prefix
            backend:
              service:
                name: transfer-service
                port: { number: 8080 }
